--
-- Table structure for table `fraud_protection_settings`
--

CREATE TABLE `fraud_protection_settings` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `duplicate_protection_enabled` tinyint(1) NOT NULL DEFAULT 0,
  `order_interval_enabled` tinyint(1) NOT NULL DEFAULT 0,
  `order_interval_minutes` int(11) NOT NULL DEFAULT 60 COMMENT 'Minutes to wait before next order',
  `pending_order_restriction_enabled` tinyint(1) NOT NULL DEFAULT 0,
  `fake_protection_enabled` tinyint(1) NOT NULL DEFAULT 0,
  `phone_validation_enabled` tinyint(1) NOT NULL DEFAULT 0,
  `phone_whitelist_enabled` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Enable phone number whitelist validation',
  `allowed_phone_lengths` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'e.g., [11, 12, 14]' CHECK (json_valid(`allowed_phone_lengths`)),
  `name_validation_enabled` tinyint(1) NOT NULL DEFAULT 0,
  `name_min_length` smallint(5) UNSIGNED NOT NULL DEFAULT 2,
  `name_max_length` smallint(5) UNSIGNED NOT NULL DEFAULT 100,
  `name_disallow_numeric` tinyint(1) NOT NULL DEFAULT 1,
  `block_sequential_numbers` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Block 000000, 111111, etc.',
  `block_repeated_names` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Block aaaa, bbbb, etc.',
  `block_gibberish_names` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Block random text like asdfgh',
  `custom_pattern_enabled` tinyint(1) NOT NULL DEFAULT 0,
  `blocked_phone_patterns` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Custom phone patterns to block' CHECK (json_valid(`blocked_phone_patterns`)),
  `blocked_name_patterns` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Custom name patterns to block' CHECK (json_valid(`blocked_name_patterns`)),
  `blocked_address_patterns` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Custom address patterns to block' CHECK (json_valid(`blocked_address_patterns`)),
  `address_validation_enabled` tinyint(1) NOT NULL DEFAULT 0,
  `address_min_length` smallint(5) UNSIGNED NOT NULL DEFAULT 10,
  `fraud_protection_enabled` tinyint(1) NOT NULL DEFAULT 0,
  `blacklist_enabled` tinyint(1) NOT NULL DEFAULT 0,
  `blacklisted_phones` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`blacklisted_phones`)),
  `blacklisted_ips` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`blacklisted_ips`)),
  `ip_rate_limiting_enabled` tinyint(1) NOT NULL DEFAULT 0,
  `ip_max_orders_per_hour` int(11) NOT NULL DEFAULT 5 COMMENT 'Max orders per IP per hour',
  `courier_success_check_enabled` tinyint(1) NOT NULL DEFAULT 0,
  `min_success_rate` decimal(5,2) NOT NULL DEFAULT 20.00 COMMENT 'Minimum courier success rate %',
  `max_bad_history_rate` decimal(5,2) NOT NULL DEFAULT 80.00 COMMENT 'Maximum bad history rate %',
  `send_admin_alerts` tinyint(1) NOT NULL DEFAULT 0,
  `admin_alert_email` varchar(255) DEFAULT NULL,
  `log_blocked_attempts` tinyint(1) NOT NULL DEFAULT 1,
  `duplicate_order_message` text DEFAULT NULL,
  `fake_data_message` text DEFAULT NULL,
  `fraud_detected_message` text DEFAULT NULL,
  `blacklist_message` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

