--
-- Table structure for table `order_items`
--

CREATE TABLE `order_items` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `order_id` bigint(20) UNSIGNED NOT NULL,
  `product_id` bigint(20) UNSIGNED NOT NULL,
  `vendor_id` bigint(20) UNSIGNED DEFAULT NULL,
  `option_id` bigint(20) UNSIGNED DEFAULT NULL,
  `combination_id` bigint(20) UNSIGNED DEFAULT NULL,
  `quantity` int(11) NOT NULL,
  `price` decimal(14,2) NOT NULL,
  `sub_total` decimal(14,2) NOT NULL,
  `unit_cost` decimal(10,2) NOT NULL DEFAULT 0.00,
  `total_cost` decimal(10,2) NOT NULL DEFAULT 0.00,
  `others` longtext DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `vendor_commission_rate` decimal(5,2) NOT NULL DEFAULT 0.00 COMMENT 'Commission % for this specific item (from product)',
  `vendor_commission_amount` decimal(14,2) NOT NULL DEFAULT 0.00 COMMENT 'Commission amount you keep',
  `vendor_earning` decimal(14,2) NOT NULL DEFAULT 0.00 COMMENT 'Net amount vendor earns from this item',
  `vendor_paid` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Has vendor been paid for this item?',
  `vendor_paid_at` timestamp NULL DEFAULT NULL,
  `paid_in_withdrawal_id` bigint(20) UNSIGNED DEFAULT NULL COMMENT 'Which withdrawal request this was paid in'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

