--
-- Table structure for table `pages`
--

CREATE TABLE `pages` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `title` varchar(255) NOT NULL,
  `slug` varchar(255) NOT NULL,
  `status` tinyint(1) NOT NULL DEFAULT 1,
  `content` text NOT NULL,
  `seo` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`seo`)),
  `meta_title` varchar(255) DEFAULT NULL,
  `meta_description` text DEFAULT NULL,
  `meta_keywords` text DEFAULT NULL,
  `canonical_url` varchar(255) DEFAULT NULL,
  `meta_robots` varchar(255) NOT NULL DEFAULT 'index,follow',
  `og_image` varchar(255) DEFAULT NULL,
  `og_image_alt` varchar(255) DEFAULT NULL,
  `schema_markup` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Dumping data for table `pages`
--

INSERT INTO `pages` (`id`, `title`, `slug`, `status`, `content`, `seo`, `meta_title`, `meta_description`, `meta_keywords`, `canonical_url`, `meta_robots`, `og_image`, `og_image_alt`, `schema_markup`, `created_at`, `updated_at`) VALUES
(1, 'About Us', 'about', 1, '<h2>Welcome to Our Company</h2><p>We are a leading provider of innovative solutions in the technology industry. Our mission is to deliver exceptional products and services that exceed customer expectations.</p><h3>Our Story</h3><p>Founded in 2020, we have grown from a small startup to a recognized leader in our field. Our team of dedicated professionals works tirelessly to bring you the best solutions.</p><h3>Our Values</h3><ul><li>Innovation</li><li>Quality</li><li>Customer Satisfaction</li><li>Integrity</li></ul>', '{\"og_image\": null, \"meta_title\": \"About Us - Learn About Our Company & Mission\", \"meta_robots\": \"index,follow\", \"og_image_alt\": \"About Us - Our Company Team and Mission\", \"canonical_url\": \"https://example.com/about-us\", \"meta_keywords\": \"about us, company, mission, values, team, innovation, quality\", \"schema_markup\": \"{\\\"@context\\\":\\\"https://schema.org\\\",\\\"@type\\\":\\\"AboutPage\\\",\\\"name\\\":\\\"About Us\\\",\\\"description\\\":\\\"Learn about our company, mission, and values\\\",\\\"url\\\":\\\"https://example.com/about-us\\\",\\\"mainEntity\\\":{\\\"@type\\\":\\\"Organization\\\",\\\"name\\\":\\\"Our Company\\\",\\\"description\\\":\\\"Leading provider of innovative solutions\\\"}}\", \"meta_description\": \"Discover our company story, mission, and values. Learn about our innovative solutions and dedicated team that delivers exceptional products and services.\", \"existing_og_image\": null}', 'About Us - Learn About Our Company & Mission', 'Discover our company story, mission, and values. Learn about our innovative solutions and dedicated team that delivers exceptional products and services.', 'about us, company, mission, values, team, innovation, quality', 'https://example.com/about-us', 'index,follow', NULL, 'About Us - Our Company Team and Mission', '{\"@context\":\"https://schema.org\",\"@type\":\"AboutPage\",\"name\":\"About Us\",\"description\":\"Learn about our company, mission, and values\",\"url\":\"https://example.com/about-us\",\"mainEntity\":{\"@type\":\"Organization\",\"name\":\"Our Company\",\"description\":\"Leading provider of innovative solutions\"}}', '2025-09-09 09:48:11', '2025-12-01 12:50:07'),
(2, 'Privacy Policy', 'privacy-policy', 1, '<h2>Privacy Policy</h2><p>Your privacy is important to us. This privacy policy explains how we collect, use, and protect your personal information.</p><h3>Information We Collect</h3><p>We collect information you provide directly to us, such as when you create an account, make a purchase, or contact us for support.</p><h3>How We Use Your Information</h3><p>We use the information we collect to provide, maintain, and improve our services, process transactions, and communicate with you.</p><h3>Data Security</h3><p>We implement appropriate security measures to protect your personal information against unauthorized access, alteration, disclosure, or destruction.</p>', '{\"og_image\": null, \"meta_title\": \"Privacy Policy - How We Protect Your Data\", \"meta_robots\": \"index,follow\", \"og_image_alt\": \"Privacy Policy - Data Protection and Security\", \"canonical_url\": \"https://example.com/privacy-policy\", \"meta_keywords\": \"privacy policy, data protection, personal information, security, GDPR\", \"schema_markup\": \"{\\\"@context\\\":\\\"https://schema.org\\\",\\\"@type\\\":\\\"WebPage\\\",\\\"name\\\":\\\"Privacy Policy\\\",\\\"description\\\":\\\"How we protect your data and personal information\\\",\\\"url\\\":\\\"https://example.com/privacy-policy\\\",\\\"isPartOf\\\":{\\\"@type\\\":\\\"WebSite\\\",\\\"name\\\":\\\"Our Website\\\"}}\", \"meta_description\": \"Read our comprehensive privacy policy to understand how we collect, use, and protect your personal information and data security practices.\"}', 'Privacy Policy - How We Protect Your Data', 'Read our comprehensive privacy policy to understand how we collect, use, and protect your personal information and data security practices.', 'privacy policy, data protection, personal information, security, GDPR', 'https://example.com/privacy-policy', 'index,follow', NULL, 'Privacy Policy - Data Protection and Security', '{\"@context\":\"https://schema.org\",\"@type\":\"WebPage\",\"name\":\"Privacy Policy\",\"description\":\"How we protect your data and personal information\",\"url\":\"https://example.com/privacy-policy\",\"isPartOf\":{\"@type\":\"WebSite\",\"name\":\"Our Website\"}}', '2025-09-09 09:48:11', '2025-09-09 09:48:11'),
(3, 'Terms of Service', 'terms-of-service', 1, '<h2>Terms of Service</h2><p>These terms of service govern your use of our website and services. By using our services, you agree to these terms.</p><h3>Acceptance of Terms</h3><p>By accessing and using this website, you accept and agree to be bound by the terms and provision of this agreement.</p><h3>Use License</h3><p>Permission is granted to temporarily download one copy of the materials on our website for personal, non-commercial transitory viewing only.</p><h3>Disclaimer</h3><p>The materials on our website are provided on an \"as is\" basis. We make no warranties, expressed or implied, and hereby disclaim all other warranties.</p>', '{\"og_image\": null, \"meta_title\": \"Terms of Service - Legal Terms & Conditions\", \"meta_robots\": \"index,follow\", \"og_image_alt\": \"Terms of Service - Legal Terms and Conditions\", \"canonical_url\": \"https://example.com/terms-of-service\", \"meta_keywords\": \"terms of service, legal terms, conditions, agreement, license\", \"schema_markup\": \"{\\\"@context\\\":\\\"https://schema.org\\\",\\\"@type\\\":\\\"WebPage\\\",\\\"name\\\":\\\"Terms of Service\\\",\\\"description\\\":\\\"Legal terms and conditions for using our services\\\",\\\"url\\\":\\\"https://example.com/terms-of-service\\\",\\\"isPartOf\\\":{\\\"@type\\\":\\\"WebSite\\\",\\\"name\\\":\\\"Our Website\\\"}}\", \"meta_description\": \"Read our terms of service to understand the legal terms and conditions for using our website and services.\"}', 'Terms of Service - Legal Terms & Conditions', 'Read our terms of service to understand the legal terms and conditions for using our website and services.', 'terms of service, legal terms, conditions, agreement, license', 'https://example.com/terms-of-service', 'index,follow', NULL, 'Terms of Service - Legal Terms and Conditions', '{\"@context\":\"https://schema.org\",\"@type\":\"WebPage\",\"name\":\"Terms of Service\",\"description\":\"Legal terms and conditions for using our services\",\"url\":\"https://example.com/terms-of-service\",\"isPartOf\":{\"@type\":\"WebSite\",\"name\":\"Our Website\"}}', '2025-09-09 09:48:11', '2025-09-09 09:48:11'),
(4, 'Contact Us', 'contact-us', 1, '<h2>Get in Touch</h2><p>We would love to hear from you. Send us a message and we will respond as soon as possible.</p><h3>Contact Information</h3><p><strong>Address:</strong> 123 Business Street, City, State 12345</p><p><strong>Phone:</strong> (555) 123-4567</p><p><strong>Email:</strong> info@example.com</p><h3>Business Hours</h3><p>Monday - Friday: 9:00 AM - 6:00 PM</p><p>Saturday: 10:00 AM - 4:00 PM</p><p>Sunday: Closed</p><h3>Send us a Message</h3><p>Use our contact form to send us a message directly. We typically respond within 24 hours.</p>', '{\"og_image\": null, \"meta_title\": \"Contact Us - Get in Touch with Our Team\", \"meta_robots\": \"index,follow\", \"og_image_alt\": \"Contact Us - Get in Touch with Our Team\", \"canonical_url\": \"https://example.com/contact-us\", \"meta_keywords\": \"contact us, support, customer service, get in touch, help\", \"schema_markup\": \"{\\\"@context\\\":\\\"https://schema.org\\\",\\\"@type\\\":\\\"ContactPage\\\",\\\"name\\\":\\\"Contact Us\\\",\\\"description\\\":\\\"Get in touch with our team\\\",\\\"url\\\":\\\"https://example.com/contact-us\\\",\\\"mainEntity\\\":{\\\"@type\\\":\\\"Organization\\\",\\\"name\\\":\\\"Our Company\\\",\\\"address\\\":{\\\"@type\\\":\\\"PostalAddress\\\",\\\"streetAddress\\\":\\\"123 Business Street\\\",\\\"addressLocality\\\":\\\"City\\\",\\\"addressRegion\\\":\\\"State\\\",\\\"postalCode\\\":\\\"12345\\\",\\\"addressCountry\\\":\\\"US\\\"},\\\"telephone\\\":\\\"(555) 123-4567\\\",\\\"email\\\":\\\"info@example.com\\\"}}\", \"meta_description\": \"Contact us for support, questions, or inquiries. Find our contact information, business hours, and send us a message directly.\"}', 'Contact Us - Get in Touch with Our Team', 'Contact us for support, questions, or inquiries. Find our contact information, business hours, and send us a message directly.', 'contact us, support, customer service, get in touch, help', 'https://example.com/contact-us', 'index,follow', NULL, 'Contact Us - Get in Touch with Our Team', '{\"@context\":\"https://schema.org\",\"@type\":\"ContactPage\",\"name\":\"Contact Us\",\"description\":\"Get in touch with our team\",\"url\":\"https://example.com/contact-us\",\"mainEntity\":{\"@type\":\"Organization\",\"name\":\"Our Company\",\"address\":{\"@type\":\"PostalAddress\",\"streetAddress\":\"123 Business Street\",\"addressLocality\":\"City\",\"addressRegion\":\"State\",\"postalCode\":\"12345\",\"addressCountry\":\"US\"},\"telephone\":\"(555) 123-4567\",\"email\":\"info@example.com\"}}', '2025-09-09 09:48:11', '2025-09-09 09:48:11'),
(5, 'FAQ', 'frequently-asked-questions', 1, '<h2>Frequently Asked Questions</h2><p>Find answers to the most common questions about our products and services.</p><h3>General Questions</h3><p><strong>Q: What is your return policy?</strong></p><p>A: We offer a 30-day return policy for all products in original condition.</p><p><strong>Q: How long does shipping take?</strong></p><p>A: Standard shipping takes 3-5 business days, while express shipping takes 1-2 business days.</p><h3>Technical Support</h3><p><strong>Q: How do I contact technical support?</strong></p><p>A: You can reach our technical support team via email at support@example.com or phone at (555) 123-4567.</p>', '{\"og_image\": null, \"meta_title\": \"FAQ - Frequently Asked Questions & Answers\", \"meta_robots\": \"index,follow\", \"og_image_alt\": \"FAQ - Frequently Asked Questions\", \"canonical_url\": \"https://example.com/faq\", \"meta_keywords\": \"FAQ, frequently asked questions, help, support, answers, shipping, returns\", \"schema_markup\": \"{\\\"@context\\\":\\\"https://schema.org\\\",\\\"@type\\\":\\\"FAQPage\\\",\\\"name\\\":\\\"Frequently Asked Questions\\\",\\\"description\\\":\\\"Common questions and answers about our products and services\\\",\\\"url\\\":\\\"https://example.com/faq\\\",\\\"mainEntity\\\":[{\\\"@type\\\":\\\"Question\\\",\\\"name\\\":\\\"What is your return policy?\\\",\\\"acceptedAnswer\\\":{\\\"@type\\\":\\\"Answer\\\",\\\"text\\\":\\\"We offer a 30-day return policy for all products in original condition.\\\"}},{\\\"@type\\\":\\\"Question\\\",\\\"name\\\":\\\"How long does shipping take?\\\",\\\"acceptedAnswer\\\":{\\\"@type\\\":\\\"Answer\\\",\\\"text\\\":\\\"Standard shipping takes 3-5 business days, while express shipping takes 1-2 business days.\\\"}}]}\", \"meta_description\": \"Find answers to frequently asked questions about our products, services, shipping, returns, and technical support.\"}', 'FAQ - Frequently Asked Questions & Answers', 'Find answers to frequently asked questions about our products, services, shipping, returns, and technical support.', 'FAQ, frequently asked questions, help, support, answers, shipping, returns', 'https://example.com/faq', 'index,follow', NULL, 'FAQ - Frequently Asked Questions', '{\"@context\":\"https://schema.org\",\"@type\":\"FAQPage\",\"name\":\"Frequently Asked Questions\",\"description\":\"Common questions and answers about our products and services\",\"url\":\"https://example.com/faq\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"What is your return policy?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"We offer a 30-day return policy for all products in original condition.\"}},{\"@type\":\"Question\",\"name\":\"How long does shipping take?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Standard shipping takes 3-5 business days, while express shipping takes 1-2 business days.\"}}]}', '2025-09-09 09:48:11', '2025-09-09 09:48:11'),
(6, 'Return and Exchange Policy', 'return-exchange', 1, '<h2>Return and Exchange Policy</h2><p>We want you to be completely satisfied with your purchase. Here is our return and exchange policy.</p><h3>Return Policy</h3><p>You have 30 days from the date of purchase to return items for a full refund. Items must be in original condition with tags attached.</p><h3>Exchange Policy</h3><p>We offer free exchanges within 30 days of purchase. Simply contact us to initiate an exchange.</p><h3>How to Return</h3><p>1. Contact our customer service team</p><p>2. Receive a return authorization number</p><p>3. Package the item securely</p><p>4. Send it back to us</p>', '{\"og_image\": null, \"meta_title\": \"Return & Exchange Policy - 30 Day Returns\", \"meta_robots\": \"index,follow\", \"og_image_alt\": \"Return and Exchange Policy - 30 Day Returns\", \"canonical_url\": \"https://example.com/return-exchange\", \"meta_keywords\": \"return policy, exchange policy, refunds, 30 day returns, customer service\", \"schema_markup\": \"{\\\"@context\\\":\\\"https://schema.org\\\",\\\"@type\\\":\\\"WebPage\\\",\\\"name\\\":\\\"Return and Exchange Policy\\\",\\\"description\\\":\\\"Our return and exchange policy for customer satisfaction\\\",\\\"url\\\":\\\"https://example.com/return-exchange\\\",\\\"isPartOf\\\":{\\\"@type\\\":\\\"WebSite\\\",\\\"name\\\":\\\"Our Website\\\"}}\", \"meta_description\": \"Learn about our return and exchange policy. 30-day returns, free exchanges, and easy return process for your peace of mind.\"}', 'Return & Exchange Policy - 30 Day Returns', 'Learn about our return and exchange policy. 30-day returns, free exchanges, and easy return process for your peace of mind.', 'return policy, exchange policy, refunds, 30 day returns, customer service', 'https://example.com/return-exchange', 'index,follow', NULL, 'Return and Exchange Policy - 30 Day Returns', '{\"@context\":\"https://schema.org\",\"@type\":\"WebPage\",\"name\":\"Return and Exchange Policy\",\"description\":\"Our return and exchange policy for customer satisfaction\",\"url\":\"https://example.com/return-exchange\",\"isPartOf\":{\"@type\":\"WebSite\",\"name\":\"Our Website\"}}', '2025-09-09 09:48:11', '2025-09-09 09:48:11'),
(9, 'This is a test page', 'this-is-a-test-page', 1, '<p>This is a test page</p>', '{\"og_image\": \"pages/seo/gH3tUEWjm6syJkRaonBfAI3BPRtJFpvCnkL5S9IZ.jpg\", \"meta_title\": \"This is a test page\", \"meta_robots\": \"noindex,follow\", \"og_image_alt\": \"This is a test page\", \"canonical_url\": \"http://127.0.0.1:8000/bongoglass\", \"meta_keywords\": \"This is a test page\", \"schema_markup\": null, \"meta_description\": \"This is a test page\"}', 'This is a test page', 'This is a test page', 'This is a test page', 'http://127.0.0.1:8000/bongoglass', 'noindex,follow', 'pages/seo/gH3tUEWjm6syJkRaonBfAI3BPRtJFpvCnkL5S9IZ.jpg', 'This is a test page', NULL, '2025-09-09 11:27:14', '2025-09-09 11:27:14');

